-- mod-supply-logistics: world rows. Generated by tools/build_data.py from tools/catalog.py and data/*.tsv;
-- change those and run it again rather than editing this file.

-- The module's own tables: what each Waylaid Crate takes and becomes, what each writ is, and
-- the reputation each hand-in pays (the module pays it to the player's own side).
CREATE TABLE IF NOT EXISTS `mod_supply_logistics_crate` (
  `item` INT UNSIGNED NOT NULL, `tier` TINYINT UNSIGNED NOT NULL, `crafted` TINYINT UNSIGNED NOT NULL,
  `kind` TINYINT UNSIGNED NOT NULL,
  `sealed` INT UNSIGNED NOT NULL, PRIMARY KEY (`item`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `mod_supply_logistics_bundle` (
  `crate` INT UNSIGNED NOT NULL, `slot` TINYINT UNSIGNED NOT NULL, `reagent` INT UNSIGNED NOT NULL,
  `count` INT UNSIGNED NOT NULL, PRIMARY KEY (`crate`, `slot`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DROP TABLE IF EXISTS `mod_supply_logistics_writ`;
CREATE TABLE `mod_supply_logistics_writ` (
  `writ` INT UNSIGNED NOT NULL, `quest` INT UNSIGNED NOT NULL, `tier` TINYINT UNSIGNED NOT NULL,
  `skill` SMALLINT UNSIGNED NOT NULL, `skill2` SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`writ`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `mod_supply_logistics_quest` (
  `quest` INT UNSIGNED NOT NULL, `rep` INT UNSIGNED NOT NULL, PRIMARY KEY (`quest`))
  ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `mod_supply_logistics_crate`;
DELETE FROM `mod_supply_logistics_bundle`;
DELETE FROM `mod_supply_logistics_writ`;
DELETE FROM `mod_supply_logistics_quest`;

